const scrollAllResult = await browserjs(tabId, async () => {
  let prevHeight = 0;
  let attempts = 0;

  while (attempts < 20) {
    const currentHeight = document.body.scrollHeight;
    window.scrollTo(0, currentHeight);
    await new Promise(r => setTimeout(r, 600));
    const newHeight = document.body.scrollHeight;
    if (newHeight === currentHeight) {
      attempts++;
    } else {
      attempts = 0;
    }
  }

  // Now collect all items
  const items = Array.from(document.querySelectorAll('ul.resultslist-content > li')).map(li => {
    if (li.classList.contains('list-label')) return null;
    const h2 = li.querySelector('h2');
    if (!h2) return null;
    const name = h2.innerText.trim();

    // Rating
    const rateVal = li.querySelector('[role="slider"]')?.getAttribute('value') || 
                    li.querySelector('.webmd-rate')?.getAttribute('aria-valuenow');

    // Extract rating count and text
    const rateText = li.querySelector('a[href*="ratings"], .webmd-rate + span, a[title*="Ratings"]')?.innerText?.trim();

    // Full text
    const text = li.innerText;

    // Correct distance regex: look for "X.XX miles" where X.XX is 1-3 digits before decimal
    // If text has zip code immediately before miles: e.g. "1178744.04 miles"
    let dist = null;
    const distMatch = text.match(/(\d+\.\d+|\d+)\s*miles/);
    if (distMatch) {
      const raw = distMatch[1];
      // if raw has more than 5 characters or starts with a 5-digit zip code
      if (raw.length > 5 && /^\d{5}/.test(raw)) {
        dist = parseFloat(raw.slice(5));
      } else {
        dist = parseFloat(raw);
      }
    }

    const addrMatch = text.match(/\d+[^,\n]+,[^,\n]+,\s*[A-Z]{2},\s*\d{5}/);

    return {
      name,
      rating: rateVal,
      ratingDetails: rateText,
      distance: dist,
      address: addrMatch ? addrMatch[0] : null
    };
  }).filter(Boolean);

  // Deduplicate
  const map = new Map();
  for (const item of items) {
    if (!map.has(item.name)) {
      map.set(item.name, item);
    }
  }

  return {
    totalLoaded: map.size,
    list: Array.from(map.values())
  };
});

