const tabId = 730410078;
const vueDetails = await browserjs(tabId, () => {
  const p = document.querySelectorAll('.webmd-popover')[5];
  const slider = p.querySelector('.webmd-slider');
  // Check Vue 2 / Vue 3
  const vnode = slider.__vue__ || slider.__vueParentComponent || slider._vnode;
  let component = null;
  if (slider.__vue__) {
    component = 'Vue2: ' + Object.keys(slider.__vue__);
  } else {
    // Check elements up
    let el = slider;
    while (el && !el.__vue__ && !el.__vue_app__) {
      el = el.parentElement;
    }
    if (el) {
      component = el.__vue__ ? 'Vue2 on parent' : 'Vue3 app';
    }
  }
  return { component };
});
console.log(vueDetails);

