const tabId = 730410078;
const pageData = await browserjs(tabId, () => {
  // Let's get total results text
  const totalResultsEl = document.querySelector('.results-count, .resultslist-total, .search-count, .serp-count, h1 + span, h1 ~ label');
  const h1 = document.querySelector('h1')?.innerText;

  // Let's extract provider cards
  const cards = Array.from(document.querySelectorAll('.resultslist-content li, article.provider-card, .resultslist-content article')).map(card => {
    const nameEl = card.querySelector('h2, .provider-name');
    const ratingEl = card.querySelector('.webmd-rate, [role="slider"]');
    const ratingText = card.querySelector('.rating-number, .rating-value, .webmd-rate + span, a[href*="ratings"]')?.innerText;
    const reviewCountEl = card.querySelector('.rating-count, .ratings-total');
    const distanceEl = card.querySelector('.distance, .provider-distance');
    const addressEl = card.querySelector('address, .provider-address');
    const specialtyEl = card.querySelector('.prov-specialty, .provider-specialty, p');

    return {
      name: nameEl?.innerText?.trim(),
      ratingValue: ratingEl?.getAttribute('aria-valuenow') || ratingEl?.getAttribute('value'),
      ratingText: ratingText?.trim(),
      reviewCount: reviewCountEl?.innerText?.trim(),
      allText: card.innerText?.slice(0, 300)
    };
  }).filter(c => c.name);

  return {
    h1,
    resultsCountText: document.body.innerText.match(/\d+\s+Results/)?.[0],
    cardsCount: cards.length,
    cards: cards.slice(0, 10)
  };
});

console.log(JSON.stringify(pageData, null, 2));

