const tabId = 730410078;
const pageDetails = await browserjs(tabId, () => {
  // Check bottom of results list
  const resultsList = document.querySelector('.resultslist-content, ul.resultslist');
  const items = Array.from(document.querySelectorAll('li.ep, li.sp, li.np, .resultslist-content > li')).map(li => {
    const h2 = li.querySelector('h2');
    const rating = li.querySelector('.webmd-rate');
    const ratingCount = li.querySelector('a[href*="ratings"], .webmd-rate + span, a[title*="Ratings"]');
    const dist = li.innerText.match(/([\d\.]+)\s*miles/)?.[1];
    const address = li.innerText.match(/(?:[A-Z0-9\s,\.\#-]+,\s*[A-Z]{2},\s*\d{5})/)?.[0];
    return {
      name: h2?.innerText?.trim(),
      rating: rating?.getAttribute('aria-valuenow'),
      ratingText: ratingCount?.innerText?.trim(),
      distance: dist,
      snippet: li.innerText.slice(0, 200)
    };
  }).filter(x => x.name);

  // Check pagination / next page buttons
  const pager = document.querySelector('.webmd-pagination, [class*="pagination"], [class*="pager"]');
  const allButtons = Array.from(document.querySelectorAll('button, a')).map(b => b.innerText.trim()).filter(t => t.match(/^\d+$/) || t.includes('Next') || t.includes('Page'));

  return {
    itemCount: items.length,
    items,
    pagerHTML: pager?.outerHTML?.slice(0, 500),
    pagingButtons: allButtons
  };
});

