const tabId = 730410078;
const rawData = await browserjs(tabId, () => {
  // Check window object or vue components for results data
  const keys = Object.keys(window).filter(k => k.toLowerCase().includes('data') || k.toLowerCase().includes('solr') || k.toLowerCase().includes('search') || k.toLowerCase().includes('result'));

  // Also check if any element has __vue__
  let doctors = null;
  const allEl = document.querySelectorAll('*');
  for (const el of allEl) {
    if (el.__vue__) {
      const v = el.__vue__;
      if (v.searchResults || v.results || v.providers || v.doctors || v.resultsList) {
        doctors = {
          searchResults: v.searchResults?.length,
          results: v.results?.length,
          providers: v.providers?.length,
          keys: Object.keys(v).filter(k => Array.isArray(v[k]))
        };
        break;
      }
    }
  }
  return { keys, doctors };
});
console.log(rawData);

