const tabId = 730410078;
const renderedDoctors = await browserjs(tabId, () => {
  const articles = Array.from(document.querySelectorAll('.resultslist-content article, .resultslist-content li')).map(el => {
    const name = el.querySelector('h2')?.innerText?.trim();
    if (!name) return null;
    const rate = el.querySelector('[role="slider"]')?.getAttribute('value') || el.querySelector('.webmd-rate')?.getAttribute('aria-valuenow');
    const rateText = el.querySelector('a[href*="ratings"], .webmd-rate + span')?.innerText?.trim();
    const distMatch = el.innerText.match(/([\d\.]+)\s*miles/);
    const address = el.innerText.match(/(\d+[^,\n]+,[^,\n]+,\s*[A-Z]{2},\s*\d{5})/)?.[0];
    const quote = el.innerText.match(/"([^"]+)"/)?.[1];
    return {
      name,
      rating: rate,
      ratingDetails: rateText,
      distance: distMatch ? parseFloat(distMatch[1]) : null,
      address,
      quote
    };
  }).filter(Boolean);

  // Deduplicate by name
  const unique = [];
  const seen = new Set();
  for (const d of articles) {
    if (!seen.has(d.name)) {
      seen.add(d.name);
      unique.push(d);
    }
  }

  return unique;
});
