const tabId = 730410078;
const allResults = await browserjs(tabId, async () => {
  const doctors = [];
  const seen = new Set();

  function collect() {
    const listItems = document.querySelectorAll('ul.resultslist-content > li');
    for (const li of listItems) {
      if (li.classList.contains('list-label')) continue;
      const h2 = li.querySelector('h2');
      if (!h2) continue;
      const name = h2.innerText.trim();
      if (!name || seen.has(name)) continue;

      const rateVal = li.querySelector('[role="slider"]')?.getAttribute('value') || li.querySelector('.webmd-rate')?.getAttribute('aria-valuenow');
      const rateText = li.querySelector('a[href*="ratings"], .webmd-rate + span, a[title*="Ratings"]')?.innerText?.trim();

      // Look for miles
      let distance = null;
      const text = li.innerText;
      const m = text.match(/([0-9]+\.[0-9]+|[0-9]+)\s*miles/i);
      if (m) distance = m[1];

      // Address
      const addrMatch = text.match(/\d+[^,\n]+,[^,\n]+,\s*[A-Z]{2},\s*\d{5}/);

      seen.add(name);
      doctors.push({
        name,
        rating: rateVal,
        ratingDetails: rateText,
        distance,
        address: addrMatch ? addrMatch[0] : null,
        isFeatured: li.closest('.resultslist-content')?.querySelector('.list-label')?.innerText?.includes('Featured') && !li.previousElementSibling?.classList?.contains('list-label') // rough check
      });
    }
  }

  // Scroll down in increments to let virtual list render
  const totalHeight = document.body.scrollHeight;
  for (let y = 0; y <= totalHeight; y += 400) {
    window.scrollTo(0, y);
    collect();
    await new Promise(r => setTimeout(r, 150));
  }

  // Scroll back up slightly or to end
  window.scrollTo(0, document.body.scrollHeight);
  collect();

  return {
    totalCollected: doctors.length,
    doctors
  };
});

console.log("Total doctors collected:", allResults.totalCollected);
console.log(JSON.stringify(allResults.doctors.slice(0, 15), null, 2));

