const tabId = 730410078;

const allDoctors = await browserjs(tabId, async () => {
  // Start at top
  window.scrollTo(0, 0);
  await new Promise(r => setTimeout(r, 400));

  const map = new Map();

  function collect() {
    const listItems = document.querySelectorAll('ul.resultslist-content > li');
    for (const li of listItems) {
      if (li.classList.contains('list-label')) continue;
      const h2 = li.querySelector('h2');
      if (!h2) continue;
      const name = h2.innerText.trim();
      if (!name) continue;

      const rateVal = li.querySelector('[role="slider"]')?.getAttribute('value') || 
                      li.querySelector('.webmd-rate')?.getAttribute('aria-valuenow');
      const rateText = li.querySelector('a[href*="ratings"], .webmd-rate + span, a[title*="Ratings"]')?.innerText?.trim();

      const text = li.innerText;
      let dist = null;
      const distMatch = text.match(/(\d+\.\d+|\d+)\s*miles/);
      if (distMatch) {
        const raw = distMatch[1];
        if (raw.length > 5 && /^\d{5}/.test(raw)) {
          dist = parseFloat(raw.slice(5));
        } else {
          dist = parseFloat(raw);
        }
      }

      const addrMatch = text.match(/\d+[^,\n]+,[^,\n]+,\s*[A-Z]{2},\s*\d{5}/);

      // parse number of ratings
      let numRatings = 0;
      if (rateText) {
        const countMatch = rateText.match(/(\d+)\s*Rating/);
        if (countMatch) {
          numRatings = parseInt(countMatch[1], 10);
        }
      }

      if (!map.has(name) || (numRatings > 0 && map.get(name).numRatings === 0)) {
        map.set(name, {
          name,
          rating: rateVal,
          ratingDetails: rateText,
          numRatings,
          distance: dist,
          address: addrMatch ? addrMatch[0] : null
        });
      }
    }
  }

  // Scroll down step by step
  let currentScroll = 0;
  let noNewItemsCount = 0;
  let lastSize = 0;

  while (noNewItemsCount < 15) {
    collect();
    if (map.size > lastSize) {
      lastSize = map.size;
      noNewItemsCount = 0;
    } else {
      noNewItemsCount++;
    }

