    for (const li of items) {
      if (li.classList.contains('list-label')) continue;
      const h2 = li.querySelector('h2');
      if (!h2) continue;
      const name = h2.innerText.trim();
      if (!name || seen.has(name)) continue;

      const rateVal = li.querySelector('[role="slider"]')?.getAttribute('value') || 
                      li.querySelector('.webmd-rate')?.getAttribute('aria-valuenow');
      const rateText = li.querySelector('a[href*="ratings"], .webmd-rate + span, a[title*="Ratings"]')?.innerText?.trim();
      const text = li.innerText;
      let dist = null;
      const distMatch = text.match(/(\d+\.\d+|\d+)\s*miles/);
      if (distMatch) {
        const raw = distMatch[1];
        if (raw.length > 5 && /^\d{5}/.test(raw)) {
          dist = parseFloat(raw.slice(5));
        } else {
          dist = parseFloat(raw);
        }
      }
      const addrMatch = text.match(/\d+[^,\n]+,[^,\n]+,\s*[A-Z]{2},\s*\d{5}/);

      seen.add(name);
      list.push({
        name,
        rating: rateVal,
        ratingDetails: rateText,
