  const items = Array.from(document.querySelectorAll('ul.resultslist-content > li'));
  const faithLi = items.find(li => li.innerText.includes('Faith S Sikorski'));
  const gerriLi = items.find(li => li.innerText.includes('Gerri Competiello'));

  return {
    faith: {
      name: faithLi?.querySelector('h2')?.innerText?.trim(),
      link: faithLi?.querySelector('a')?.href,
      text: faithLi?.innerText
    },
    gerri: {
      name: gerriLi?.querySelector('h2')?.innerText?.trim(),
      link: gerriLi?.querySelector('a')?.href,
      text: gerriLi?.innerText
    }
  };
});
console.log(JSON.stringify(details, null, 2));
"}

